from __future__ import annotations
from abc_creative_gold_v5_101_200_support import make_spec, register_craft
FACTS={
"Automatic Gate":"Powered gate opens or closes access when a valid condition is met; at stations it may control fares or passenger flow, while crossing gates protect road-rail intersections.",
"Brake":"Train braking system slows wheelsets using friction, electrical/dynamic braking, air pressure, or combinations depending rolling stock.",
"Caboose":"Crew car historically placed near the rear of many North American freight trains; modern freight operations often use other systems instead.",
"Dining Car":"Passenger rail car contains tables and food service space; it is part of onboard service, not propulsion.",
"Electric Train":"Train draws electrical energy from overhead wire, third rail, batteries, or other sources depending system; traction motors turn wheels.",
"Freight Car":"Rail vehicle carries goods rather than passengers; boxcars, hoppers, tank cars, flats, and other types fit different loads.",
"Gate":"Rail/station gate controls access or protects a crossing; the pictured location determines its exact job.",
"High-speed Train":"Passenger train designed for sustained high speeds on suitable infrastructure; dedicated track geometry, signaling, and grade separation are common safety requirements.",
"Intercity Train":"Passenger service links cities, usually with fewer stops and longer distances than local transit.",
"Junction Box":"Protected enclosure houses electrical connections; railway electrical equipment is for trained workers, not passenger handling.",
"Key Switch":"Locked/key-operated control allows authorized operation of equipment; passengers do not operate railway control switches.",
"Locomotive":"Rail vehicle supplies tractive power to move itself and often other cars; power may be diesel-electric, electric, or other forms.",
"Monorail":"Railway whose vehicles are guided by or suspended from a single beam/rail structure rather than a conventional pair of running rails.",
"Number Sign":"Displayed number identifies platform, track, car, route, or other railway information depending context.",
"Overpass":"Bridge carries one route above another, separating traffic levels and reducing conflicts.",
"Platform":"Raised or level boarding area beside a track; passengers stay behind edge markings until safe boarding.",
"Queue Barrier":"Posts, rails, or belts organize waiting lines and keep passenger flow orderly.",
"Rail":"Steel running surface guides flanged train wheels; tracks are not walking paths.",
"Subway":"Urban rapid-transit railway that may run underground, elevated, or at surface; 'subway' does not mean every section is tunneled.",
"Ticket":"Proof of fare/payment or travel authorization; it carries journey information but does not control the train.",
"Utility Car":"Rail vehicle assigned maintenance, inspection, work, or support functions; exact equipment varies by railway.",
"Vestibule":"Enclosed end/entry area of a passenger car connects doors and often adjacent cars; passengers follow door and movement rules.",
"Wagon":"Railway term for a freight/passenger vehicle in some regions, while everyday English can also mean a road/hand cart; rail context matters.",
"Xpress Train":"Project label for an express-style train service; 'Xpress' is branding/spelling, while express generally means fewer stops or faster service pattern.",
"Yellow Signal":"Railway yellow aspect commonly indicates caution or a restrictive condition ahead, but exact meaning depends on the signaling system; drivers follow local rules.",
"Zone Map":"Map divides a transit network into fare, service, or geographic zones; colors/labels explain boundaries.",
"Arrival Board":"Electronic or printed display lists expected arrivals and platform/service information; times can change with operations.",
"Boxcar":"Enclosed freight car with sliding/plug doors protects general cargo from weather.",
"Engine":"Railway 'engine' can mean locomotive or its power unit; exact meaning depends on context.",
"Footbridge":"Pedestrian bridge crosses tracks above grade, keeping people away from the running rails.",
"Goods Wagon":"Freight rail vehicle used to carry goods; British/Commonwealth term overlaps freight car.",
"Information Board":"Station display gives routes, times, platforms, rules, or notices; passengers use it to plan rather than guess track access.",
"Junction":"Location where rail routes meet, split, or cross; switches and signals route trains safely.",
"Kiosk":"Small station booth or machine may sell tickets, information, or goods; function depends on station design.",
"Level Crossing":"Place where road/path crosses railway at the same level; users obey lights, bells, barriers, and never go around a closed gate.",
"Metro":"Urban rapid-transit rail system; may use tunnels, elevated structures, or surface sections.",
"Observation Car":"Passenger car designed with large windows or viewing areas for scenery; it is a service car, not a driving cab.",
"Passenger Car":"Rail car carries seated or standing passengers; doors, seating, and amenities vary by service.",
"Railway Signal":"Visual/electronic signal communicates movement authority or restrictions to train crews; meanings depend on the railway rulebook.",
"Underground Train":"Train operating on an underground/subway system or tunneled section; stations and signals govern movement.",
"Viaduct":"Long bridge-like structure carries rail or road across a valley, streets, or low ground using repeated spans/supports.",
"X-crossing Sign":"X-shaped railway-crossing warning sign marks a road-rail crossing; it warns road users, not trains to cross freely.",
"Coach":"Passenger rail car, especially for seated accommodation; coach is not the locomotive.",
"Diesel Engine":"Compression-ignition engine burns diesel fuel; diesel locomotives often use it to drive a generator feeding electric traction motors.",
"Hopper Car":"Freight car with sloped bottom gates carries loose bulk material.",
"Night Train":"Train service scheduled overnight; may include ordinary seats or sleeping accommodation depending route.",
"Quiet Car":"Passenger area with reduced conversation/device noise under operator rules.",
"Train":"One or more rail vehicles operating together on a guided track system; signals and timetable/dispatch control safe separation.",
"Waiting Room":"Station room provides sheltered waiting; official signs still guide boarding.",
"Yard Engine":"Locomotive switches/assembles cars in a restricted rail yard.",
"Zigzag Track":"Project label for winding track; real railways use engineered curves, not sharp toy zigzags.",
"Sleeper Car":"Passenger car provides berths or compartments for overnight travel; it supports rest, not train propulsion.",
}
ACTIONS={"Platform":"Point to the platform picture; draw an imaginary edge and stay behind it.","Rail":"Point only; make two parallel lines in the air—never a walking gesture on track.","Level Crossing":"Cross two fingers into an X, then show a stop palm.","Railway Signal":"Point to the signal; no 'go' gesture—meaning depends on aspect/system.","Yellow Signal":"Show a caution palm; say the exact rule depends on the railway.","Key Switch":"Point only; authorized staff operate the real control.","Junction Box":"Point only; electrical enclosure stays closed.","Automatic Gate":"Open/close two flat palms gently; never push through a real closed gate.","Gate":"Show a closed-bar shape; wait rather than go around.","X-crossing Sign":"Make an X with fingers; stop and look/listen under adult road-safety rules."}
